default.shell:
$mismatchCount = 0

$key = Get-Item -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Nt\Terminal Services' -ErrorAction SilentlyContinue
$current = $null
if ($key) { $current = $key.GetValue('MinEncryptionLevel', $null, 'DoNotExpandEnvironmentNames') }
if (-not ($current -is [int] -and [BitConverter]::ToUInt32([BitConverter]::GetBytes($current), 0) -eq [uint32]3)) {
    Write-Output 'Mismatch: HKLM:\SOFTWARE\Policies\Microsoft\Windows Nt\Terminal Services [MinEncryptionLevel]'
    $mismatchCount++
}

if ($mismatchCount -gt 0) { exit 1 }
exit 0

steps.shell:
$ErrorActionPreference = 'Stop'
trap { Write-Output $_.Exception.Message; exit 1 }

if (-not (Test-Path -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Nt\Terminal Services')) {
    New-Item -Path 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Nt\Terminal Services' -Force | Out-Null
}
New-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Policies\Microsoft\Windows Nt\Terminal Services' -Name 'MinEncryptionLevel' -Value 3 -PropertyType DWord -Force | Out-Null
exit 0
